        return .{ .value = @intFromFloat(f * 65536.0) };
    }
    pub fn toFloat(self: FixedPoint32) f32 {
        return @floatFromInt(self.value) / 65536.0;
    }
    pub fn add(a: FixedPoint32, b: FixedPoint32) FixedPoint32 {
