    pub fn mul(a: FixedPoint32, b: FixedPoint32) FixedPoint32 {
        return .{ .value = @intCast((@as(i64, a.value) * @as(i64, b.value)) >> 16) };
    }
    pub fn div(a: FixedPoint32, b: FixedPoint32) FixedPoint32 {
        return .{ .value = @intCast((@as(i64, a.value) << 16) / @as(i64, b.value)) };
    }
};

pub const Tensor = struct {
    data: []u8,
    shape: []usize,
    strides: []usize,
    elem_size: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize, comptime T: type) !Tensor {
        const elem_size = @sizeOf(T);
        var size: usize = 1;
        for (shape) |dim| size *= dim;
        const data = try allocator.alloc(u8, size * elem_size);
        @memset(data, 0);
        var strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return .{ .data = data, .shape = try allocator.dupe(usize, shape), .strides = strides, .elem_size = elem_size, .allocator = allocator };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn get(comptime T: type, self: *const Tensor, indices: []const usize) T {
        var idx: usize = 0;
        for (indices, 0..) |id, i| {
            idx += id * self.strides[i];
        }
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        return ptr[idx];
    }

    pub fn set(comptime T: type, self: *Tensor, indices: []const usize, value: T) void {
        var idx: usize = 0;
        for (indices, 0..) |id, i| {
            idx += id * self.strides[i];
        }
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        ptr[idx] = value;
    }

    pub fn copy(self: *const Tensor, allocator: std.mem.Allocator) !Tensor {
        return .{ .data = try allocator.dupe(u8, self.data), .shape = try allocator.dupe(usize, self.shape), .strides = try allocator.dupe(usize, self.strides), .elem_size = self.elem_size, .allocator = allocator };
    }

    pub fn fill(comptime T: type, self: *Tensor, value: T) void {
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] = value;
        }
    }

    pub fn addScalar(comptime T: type, self: *Tensor, value: T) void {
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] += value;
        }
    }

    pub fn subScalar(comptime T: type, self: *Tensor, value: T) void {
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] -= value;
        }
    }

    pub fn mulScalar(comptime T: type, self: *Tensor, value: T) void {
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] *= value;
        }
    }

    pub fn divScalar(comptime T: type, self: *Tensor, value: T) void {
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] /= value;
        }
    }

    pub fn add(self: *Tensor, other: *const Tensor) !void {
        if (self.elem_size != other.elem_size or !std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const size = self.data.len / self.elem_size;
        if (self.elem_size == 4) {
            const ptr1 = @ptrCast([*]f32, @alignCast(@alignOf(f32), self.data.ptr));
            const ptr2 = @ptrCast([*]const f32, @alignCast(@alignOf(f32), other.data.ptr));
            var i: usize = 0;
            while (i < size) : (i += 1) {
                ptr1[i] += ptr2[i];
            }
        } else {
            return error.UnsupportedElemSize;
        }
    }

    pub fn sub(self: *Tensor, other: *const Tensor) !void {
        if (self.elem_size != other.elem_size or !std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const size = self.data.len / self.elem_size;
        if (self.elem_size == 4) {
            const ptr1 = @ptrCast([*]f32, @alignCast(@alignOf(f32), self.data.ptr));
            const ptr2 = @ptrCast([*]const f32, @alignCast(@alignOf(f32), other.data.ptr));
            var i: usize = 0;
            while (i < size) : (i += 1) {
                ptr1[i] -= ptr2[i];
            }
        } else {
            return error.UnsupportedElemSize;
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor) !void {
        if (self.elem_size != other.elem_size or !std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const size = self.data.len / self.elem_size;
        if (self.elem_size == 4) {
            const ptr1 = @ptrCast([*]f32, @alignCast(@alignOf(f32), self.data.ptr));
            const ptr2 = @ptrCast([*]const f32, @alignCast(@alignOf(f32), other.data.ptr));
            var i: usize = 0;
            while (i < size) : (i += 1) {
                ptr1[i] *= ptr2[i];
            }
        } else {
            return error.UnsupportedElemSize;
        }
    }

    pub fn div(self: *Tensor, other: *const Tensor) !void {
        if (self.elem_size != other.elem_size or !std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const size = self.data.len / self.elem_size;
        if (self.elem_size == 4) {
            const ptr1 = @ptrCast([*]f32, @alignCast(@alignOf(f32), self.data.ptr));
            const ptr2 = @ptrCast([*]const f32, @alignCast(@alignOf(f32), other.data.ptr));
            var i: usize = 0;
            while (i < size) : (i += 1) {
                ptr1[i] /= ptr2[i];
            }
        } else {
            return error.UnsupportedElemSize;
        }
    }

    pub fn clip(self: *Tensor, min_val: f32, max_val: f32) void {
        const ptr = @ptrCast([*]f32, @alignCast(@alignOf(f32), self.data.ptr));
        const size = self.data.len / self.elem_size;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            ptr[i] = @max(min_val, @min(max_val, ptr[i]));
        }
    }
};

pub const ContextWindow = packed struct {
    tokens: [1024]u32,
    size: u32,
    pub fn add(self: *ContextWindow, token: u32) void {
        if (self.size < 1024) {
            self.tokens[self.size] = token;
            self.size += 1;
        }
    }
};

