entries.query:
ez mi?

{
  description = "JAIDE v40: Root-Level, Non-Transformer, Polyglot LLM";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";

    zig.url = "github:mitchellh/zig-overlay";

    clash.url = "github:clash-lang/clash-nix";

    lean = {
      url = "github:leanprover/lean4";
      flake = false;
    };
    isabelle = {
      url = "github:isabelle-prover/isabelle";
      flake = false;
    };
    agda = {
      url = "github:agda/agda";
      flake = false;
    };
    viper = {
      url = "github:viperproject/viperserver";
      flake = false;
    };
    tlaps = {
      url = "github:tlaplus/tlaps";
      flake = false;
    };
    spin = {
      url = "github:nimble-code/Spin";
      flake = false;
    };
    futhark = {
      url = "github:diku-dk/futhark";
      flake = false;
    };
    circom = {
      url = "github:iden3/circom";
      flake = false;
    };
    rust-overlay.url = "github:oxalica/rust-overlay";
    haskell-overlay.url = "github:haskell/haskell-nix";
  };

  outputs = { self, nixpkgs, flake-utils, ... }@inputs:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          overlays = [ inputs.zig.overlays.default inputs.rust-overlay.overlays.default inputs.haskell-overlay.overlays.default ];
        };

        lib = pkgs.lib;

        zig-master = pkgs.zigpkgs.master;
        clash-env = inputs.clash.packages.${system}.clash-ghc;
        lean-env = pkgs.lean4;
        isabelle-env = pkgs.isabelle;
        agda-env = pkgs.agda;
        viper-server = pkgs.stdenv.mkDerivation {
          name = "viperserver";
          src = inputs.viper;
          buildPhase = "sbt assembly";
          installPhase = "mkdir -p $out/bin; cp target/scala-*/viperserver.jar $out/bin/";
        };
        tlaps-env = pkgs.callPackage inputs.tlaps {};
        spin-env = pkgs.spin;
        futhark-env = pkgs.futhark;
        circom-env = pkgs.circom;

      in
      {
        devShell = pkgs.mkShell {
          name = "jaide-v40-shell";
          packages = [
            zig-master
            clash-env
            lean-env
            isabelle-env
            agda-env
            viper-server
            tlaps-env
            spin-env
            futhark-env
            circom-env
            pkgs.gcc
            pkgs.gnumake
            pkgs.bash
            pkgs.rustc
            pkgs.cargo
            pkgs.ghc
          ];

          shellHook = ''
            export JAIDE_ROOT="${toString ./.}"
            export LD_LIBRARY_PATH="$JAIDE_ROOT/build/lib:$LD_LIBRARY_PATH"
            export PATH="$PATH:${pkgs.rustc}/bin:${pkgs.cargo}/bin:${pkgs.ghc}/bin"
            echo "JAIDE v40 Development Environment Activated."
          '';
        };
      }
    );
}
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const lib = b.addStaticLibrary(.{
        .name = "jaide_v40",
        .root_source_file = .{ .path = "src/core/types.zig" },
        .target = target,
        .optimize = optimize,
    });

    lib.addIncludePath(.{ .path = "src" });
    lib.linkLibC();

    const futhark_step = b.addSystemCommand(&[_][]const u8{
        "futhark", "c", "--library", "src/hw/accel/futhark_kernels.fut", "-o", "build/futhark_kernels"
    });
    lib.step.dependOn(&futhark_step.step);
    lib.addIncludePath(.{ .path = "build" });
    lib.addCSourceFile(.{ .file = .{ .path = "build/futhark_kernels.c" }, .flags = &[_][]const u8{} });
    lib.linkLibC();

    const clash_step = b.addSystemCommand(&[_][]const u8{
        "clash", "--verilog", "src/hw/rtl/RankerCore.hs", "-o", "build/hw/ranker_core.v"
    });
    lib.step.dependOn(&clash_step.step);

    const clash_ssi_step = b.addSystemCommand(&[_][]const u8{
        "clash", "--verilog", "src/hw/rtl/SSISearch.hs", "-o", "build/hw/ssi_search.v"
    });
    lib.step.dependOn(&clash_ssi_step.step);

