pub const SSIHashTree = struct {
    root: ?*HashNode,
    allocator: std.mem.Allocator,

    pub fn insert(self: *SSIHashTree, key: u64, seg: RankedSegment) !void {
        var node = &self.root;
        while (node.*) |n| {
            if (key < n.key) node = &n.left else if (key > n.key) node = &n.right else {
                var new_val = try self.allocator.realloc(n.value, n.value.len + 1);
                new_val[n.value.len] = seg;
                n.value = new_val;
                return;
            }
        }
        const new_node = try self.allocator.create(HashNode);
        new_node.* = .{ .key = key, .value = try self.allocator.dupe(RankedSegment, &.{seg}), .left = null, .right = null };
        node.* = new_node;
    }
};

